## Code examples
Replace `YOUR_API_KEY` with the key from your dashboard.
const res = await fetch(  
  'https://api.artic.edu/api/v1/artworks?fields=id,title,artist_title,image_id&limit=12',  
);  
const { data } = await res.json();
// One identifier serves both a thumbnail and a full-screen view.  
const thumb = (id) => `https://www.artic.edu/iiif/2/${id}/full/200,/0/default.jpg`;  
const full = (id) => `https://www.artic.edu/iiif/2/${id}/full/1686,/0/default.jpg`;
data.filter((a) => a.image_id).forEach((a) => {  
  console.log(a.title, thumb(a.image_id), full(a.image_id));  
});

